  1	//! The splitting algorithm.
  2	//!
  3	//! Component boundaries are decided in a fixed order, which is what makes
  4	//! `"/path?x=http://y"` come out as a plain path plus query rather than
  5	//! sprouting a scheme:
  6	//!
  7	//! 1. the first `#` peels off the fragment,
  8	//! 2. the first `?` in what is left peels off the query,
  9	//! 3. the first `://` in what is left peels off the scheme and opens an
 10	//!    authority; without it the whole remainder is the path,
 11	//! 4. inside the authority the first `/` ends it and starts the path, the
 12	//!    first `@` splits off the userinfo, and the first `:` splits off the port.
 13	//!
 14	//! Every delimiter is ASCII, so slicing the input at the offsets found here
 15	//! never lands inside a multi-byte UTF-8 sequence.
 16	
 17	use super::port::{parse_port, NO_PORT};
 18	use super::Parts;
 19	
 20	/// Byte offset of the first occurrence of `needle` in `haystack`.
 21	fn find(haystack: &[u8], needle: u8) -> Option<usize> {
 22	    haystack.iter().position(|&b| b == needle)
 23	}
 24	
 25	/// Byte offset of the first occurrence of the `://` separator.
 26	fn find_scheme_separator(haystack: &[u8]) -> Option<usize> {
 27	    haystack.windows(3).position(|w| w == b"://")
 28	}
 29	
 30	/// ASCII-only lowercasing, matching `std::tolower` under the "C" locale:
 31	/// bytes outside `A-Z` — including every byte of a UTF-8 sequence — are kept.
 32	fn ascii_lowercase(bytes: &[u8]) -> Vec<u8> {
 33	    bytes.iter().map(|b| b.to_ascii_lowercase()).collect()
 34	}
 35	
 36	/// Splits `input` into its components.
 37	pub fn parse(input: &[u8]) -> Parts {
 38	    let mut parts = Parts {
 39	        scheme: Vec::new(),
 40	        userinfo: Vec::new(),
 41	        host: Vec::new(),
 42	        port: NO_PORT,
 43	        path: Vec::new(),
 44	        query: Vec::new(),
 45	        fragment: Vec::new(),
 46	    };
 47	
 48	    let mut rest = input;
 49	
 50	    // 1. Fragment: everything after the first '#'. A later '#' stays inside
 51	    //    the fragment, so "#a#b" yields the fragment "a#b".
 52	    if let Some(hash) = find(rest, b'#') {
 53	        parts.fragment = rest[hash + 1..].to_vec();
 54	        rest = &rest[..hash];
 55	    }
 56	
 57	    // 2. Query: everything after the first '?' of the pre-fragment text. A '?'
 58	    //    that appeared after the '#' already belongs to the fragment.
 59	    if let Some(question) = find(rest, b'?') {
 60	        parts.query = rest[question + 1..].to_vec();
 61	        rest = &rest[..question];
 62	    }
 63	
 64	    // 3. Scheme: the text before the first "://". A bare "scheme:" is not
 65	    //    enough — "mailto:user@example.com" has no scheme and no authority.
 66	    match find_scheme_separator(rest) {
 67	        Some(sep) => {
 68	            parts.scheme = ascii_lowercase(&rest[..sep]);
 69	            let after = &rest[sep + 3..];
 70	
 71	            // 4. Authority runs up to the first '/', which begins the path.
 72	            let authority = match find(after, b'/') {
 73	                Some(slash) => {
 74	                    parts.path = after[slash..].to_vec();
 75	                    &after[..slash]
 76	                }
 77	                None => after,
 78	            };
 79	
 80	            // Userinfo is delimited by the first '@'; a second '@' is left in
 81	            // the host, so "a@b@c.com" has userinfo "a" and host "b@c.com".
 82	            let host_port = match find(authority, b'@') {
 83	                Some(at) => {
 84	                    parts.userinfo = authority[..at].to_vec();
 85	                    &authority[at + 1..]
 86	                }
 87	                None => authority,
 88	            };
 89	
 90	            // The first ':' separates host from port. There is no IPv6
 91	            // bracket handling, so "[::1]:80" leaves the host as "[".
 92	            match find(host_port, b':') {
 93	                Some(colon) => {
 94	                    parts.host = host_port[..colon].to_vec();
 95	                    parts.port = parse_port(&host_port[colon + 1..]);
 96	                }
 97	                None => parts.host = host_port.to_vec(),
 98	            }
 99	        }
100	        // Without "://" there is no authority at all: the remainder, leading
101	        // slashes and colons included, is the path.
102	        None => parts.path = rest.to_vec(),
103	    }
104	
105	    parts
106	}
107	//! Port-number parsing.
108	//!
109	//! The C++ library feeds the text after the host/port `:` straight into
110	//! `std::stoi` and swallows the exceptions, then range-checks the result.
111	//! Reproducing that exactly matters: `std::stoi` skips leading whitespace,
112	//! honours a leading sign, stops at the first non-digit and only reports
113	//! failure when there are no digits at all or the value leaves `int`.
114	
115	/// Sentinel written into `URL::port` when no usable port was found.
116	pub const NO_PORT: i32 = -1;
117	
118	/// Smallest accepted port number.
119	pub const MIN_PORT: i32 = 0;
120	
121	/// Largest accepted port number.
122	pub const MAX_PORT: i32 = 65535;
123	
124	/// `std::isspace` under the default "C" locale.
125	fn is_space(b: u8) -> bool {
126	    matches!(b, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
127	}
128	
129	/// Emulates `std::stoi(text)`.
130	///
131	/// Returns `None` where the C++ call would throw: `std::invalid_argument`
132	/// when no digits could be consumed, `std::out_of_range` when the value does
133	/// not fit in an `int`.
134	pub fn stoi(text: &[u8]) -> Option<i32> {
135	    let mut i = 0;
136	    while i < text.len() && is_space(text[i]) {
137	        i += 1;
138	    }
139	
140	    let mut negative = false;
141	    if i < text.len() && (text[i] == b'+' || text[i] == b'-') {
142	        negative = text[i] == b'-';
143	        i += 1;
144	    }
145	
146	    let digits_start = i;
147	    // Accumulate in i64 and stop growing once we are provably past the `int`
148	    // range, so absurdly long digit runs cannot overflow the accumulator.
149	    let mut value: i64 = 0;
150	    let mut overflowed = false;
151	    while i < text.len() && text[i].is_ascii_digit() {
152	        if !overflowed {
153	            value = value * 10 + i64::from(text[i] - b'0');
154	            if value > i64::from(u32::MAX) {
155	                overflowed = true;
156	            }
157	        }
158	        i += 1;
159	    }
160	
161	    if i == digits_start {
162	        return None; // std::invalid_argument
163	    }
164	    if overflowed {
165	        return None; // std::out_of_range
166	    }
167	
168	    let signed = if negative { -value } else { value };
169	    if signed > i64::from(i32::MAX) || signed < i64::from(i32::MIN) {
170	        return None; // std::out_of_range
171	    }
172	    Some(signed as i32)
173	}
174	
175	/// Parses the text following the authority's `:` into a port number.
176	///
177	/// Yields [`NO_PORT`] when `std::stoi` would have thrown or when the number
178	/// falls outside `0..=65535`.
179	pub fn parse_port(text: &[u8]) -> i32 {
180	    match stoi(text) {
181	        Some(value) if (MIN_PORT..=MAX_PORT).contains(&value) => value,
182	        _ => NO_PORT,
183	    }
184	}
