224	//! Re-serialisation of parsed components.
225	//!
226	//! Neither `authority()` nor `to_string()` hands back a slice of the original
227	//! input — both are rebuilt from the parsed fields, which is why they can
228	//! differ from what was passed in. `"http://example.com:abc"` re-serialises as
229	//! `"http://example.com"` because the unusable port is simply gone, and
230	//! `"http://h/?"` loses its empty query.
231	
232	use super::port::NO_PORT;
233	use super::Parts;
234	
235	/// Rebuilds the authority as `[userinfo "@"] host [":" port]`.
236	///
237	/// The `@` appears whenever the userinfo is non-empty and the `:port` whenever
238	/// a port was accepted, independently of whether the host is empty — so an
239	/// empty host with a port renders as `":8080"`.
240	pub fn authority(parts: &Parts) -> Vec<u8> {
241	    let mut out = Vec::new();
242	    if !parts.userinfo.is_empty() {
243	        out.extend_from_slice(&parts.userinfo);
244	        out.push(b'@');
245	    }
246	    out.extend_from_slice(&parts.host);
247	    if parts.port != NO_PORT {
248	        out.push(b':');
249	        out.extend_from_slice(parts.port.to_string().as_bytes());
250	    }
251	    out
252	}
253	
254	/// Rebuilds the whole URL.
255	///
256	/// The scheme guards the authority: with an empty scheme neither `://` nor the
257	/// authority is emitted, so `"://h/p"` serialises as just `"/p"`. The `?` and
258	/// `#` markers are emitted only for non-empty components.
259	pub fn to_string(parts: &Parts) -> Vec<u8> {
260	    let mut out = Vec::new();
261	    if !parts.scheme.is_empty() {
262	        out.extend_from_slice(&parts.scheme);
263	        out.extend_from_slice(b"://");
264	        out.extend_from_slice(&authority(parts));
265	    }
266	    out.extend_from_slice(&parts.path);
267	    if !parts.query.is_empty() {
268	        out.push(b'?');
269	        out.extend_from_slice(&parts.query);
270	    }
271	    if !parts.fragment.is_empty() {
272	        out.push(b'#');
273	        out.extend_from_slice(&parts.fragment);
274	    }
275	    out
276	}
277	//! A byte-faithful reimplementation of the C++ `url_parser::URL` class.
278	//!
279	//! Components are held as raw bytes rather than `String`s so that any argument
280	//! the shell hands over survives untouched: the parser never inspects anything
281	//! but ASCII delimiters, and never re-encodes or percent-decodes.
282	
