#!/usr/bin/perl
use strict; use warnings;
use POSIX ":sys_wait_h";
my $CPP="/workspace/dataset/test18_executable";
my $RS="/output/test18";

sub runone {
  my ($bin,$arg)=@_;
  pipe(my $r, my $w) or die;
  my $pid=fork(); die "fork" unless defined $pid;
  if(!$pid){ close $r; open(STDOUT,">&",$w) or die; open(STDERR,">","/dev/null"); close $w;
     exec($bin, $arg) or POSIX::_exit(127); }
  close $w;
  local $/; my $out=<$r>; $out='' unless defined $out; close $r;
  waitpid($pid,0); my $st=$?;
  my $code = ($st & 127) ? -($st & 127) : ($st >> 8);
  return ($out,$code);
}

# reads NUL-separated inputs from file given on cmdline, or from labeled file
my $file=shift @ARGV;
open(my $fh,'<',$file) or die; binmode $fh; local $/="\0";
my ($n,$f)=(0,0);
while(my $line=<$fh>){
  chomp $line if 0; $line =~ s/\0$//;
  $n++;
  my ($oa,$ca)=runone($CPP,$line);
  my ($ob,$cb)=runone($RS,$line);
  if($oa ne $ob || $ca != $cb){
    $f++;
    my $lbl = length($line)>120 ? "len=".length($line)." head=[".substr($line,0,60)."] tail=[".substr($line,-30)."]" : "[$line]";
    print "MISMATCH #$f len=".length($line)." exit cpp=$ca rs=$cb  $lbl\n";
    my @A=split /\n/, $oa, -1; my @B=split /\n/, $ob, -1;
    for my $i (0..(($#A>$#B)?$#A:$#B)){
      my $a = defined $A[$i] ? $A[$i] : '<none>';
      my $b = defined $B[$i] ? $B[$i] : '<none>';
      if($a ne $b){ printf("  line %d: cpp=%s\n           rs =%s\n", $i+1,
         (length($a)>100? "len".length($a).":".substr($a,0,50)."...".substr($a,-20) : "<<$a>>"),
         (length($b)>100? "len".length($b).":".substr($b,0,50)."...".substr($b,-20) : "<<$b>>")); }
    }
  }
}
print "=== total=$n mismatches=$f\n";
EOF
